// Navigation and presentation only; existing save, trade and study handlers remain authoritative.
(()=>{
const campus=!!document.querySelector('#studyPage'),esc=growthEscape;
let screen=campus?(['#travel','#passport'].includes(location.hash)?'passport':'study'):'farm',passportTab=location.hash==='#travel'?'travel':'stamps',stampPage=0,activity='quiz',zone='library',studyTab='seats',seatPage=0;
document.body.classList.add('compact-shell');if(campus)document.body.classList.add('campus-shell');
const bar=document.createElement('div');bar.className='compact-topline';bar.innerHTML='<span id="compactWeather">Shiny Village</span><button id="compactPrices">오늘 시세 ▾</button><button id="compactMenuButton" aria-expanded="false">☰ 메뉴</button>';document.querySelector('header').after(bar);const navNote=document.querySelector('#studentNavigationStatus');if(navNote){navNote.className='compact-feedback';bar.after(navNote)}
const priceBox=document.createElement('div');priceBox.className='compact-price-box';priceBox.hidden=true;bar.after(priceBox);document.querySelector('#compactPrices').onclick=()=>{priceBox.hidden=!priceBox.hidden;updateTop()};
const menu=document.createElement('dialog');menu.className='compact-menu';menu.innerHTML='<div class="compact-dialog-head"><b>마을 메뉴</b><button id="closeCompactMenu" aria-label="메뉴 닫기">×</button></div><div class="compact-menu-grid">'+[['bag','🎒 보관함'],['settings','⚙ 내 정보·설정'],['logout','로그아웃 · 학생 바꾸기']].map(([id,label])=>`<button data-menu-dest="${id}">${label}</button>`).join('')+'</div>';document.body.append(menu);if(campus){const motion=document.querySelector('.cafe-motion');if(motion)menu.append(motion);const help=document.createElement('details');help.className='cafe-help';help.innerHTML='<summary>자리 이용 안내</summary>';document.querySelector('.seat-tools').append(help);help.append(document.querySelector('.seat-legend'),document.querySelector('.interior-caption'));document.querySelector('.interior-heading h2').textContent='별빛도서관';}
const menuButton=document.querySelector('#compactMenuButton');menuButton.onclick=()=>{menu.showModal();menuButton.setAttribute('aria-expanded','true')};document.querySelector('#closeCompactMenu').onclick=()=>menu.close();menu.addEventListener('close',()=>{menuButton.setAttribute('aria-expanded','false');menuButton.focus()});menu.onclick=e=>{const b=e.target.closest('[data-menu-dest]');if(!b)return;menu.close();navigate(b.dataset.menuDest)};
const tabs=document.createElement('nav');tabs.className='compact-tabs';tabs.setAttribute('aria-label','주요 화면');tabs.innerHTML=[['farm','내 농장'],['village','우리 마을'],['activity','활동'],['study','별빛도서관'],['passport','내 여권']].map(([id,t])=>`<button data-screen="${id}">${t}</button>`).join('');priceBox.after(tabs);tabs.onclick=e=>{const b=e.target.closest('[data-screen]');if(b)navigate(b.dataset.screen)};
const book=document.createElement('section');book.className='passport-book';book.innerHTML='<div class="passport-cover"><span>SHINY VILLAGE · CITIZEN PASSPORT</span><h1>나의 마을 여권</h1><p id="passportOwner"></p></div><nav class="passport-tabs" aria-label="여권 페이지">'+[['profile','◉ 프로필'],['missions','✓ 미션'],['stamps','♟ 스탬프'],['badges','✦ 배지'],['travel','마을 여행']].map(([id,t])=>`<button data-passport-tab="${id}">${t}</button>`).join('')+'</nav><div id="passportSheet"></div><div id="passportOriginal"></div>';document.querySelector('main').append(book);
if(campus){document.querySelector('#passportOriginal').append(document.querySelector('.passport'));book.append(document.querySelector('#travelPage'));const brand=document.querySelector('header>a');brand.className='brand';brand.textContent='Shiny Village';brand.href='index.html#farm';document.querySelector('header>b').hidden=true;}
book.onclick=e=>{const b=e.target.closest('[data-passport-tab]');if(b){passportTab=b.dataset.passportTab;stampPage=0;drawBook()}const n=e.target.closest('[data-stamp-page]');if(n){stampPage+=Number(n.dataset.stampPage);drawBook()}const q=e.target.closest('[data-passport-action]');if(q)navigate(q.dataset.passportAction)};
const activityBox=document.createElement('section');activityBox.className='compact-activities';activityBox.innerHTML='<nav class="activity-tabs" aria-label="활동 종류"><button data-activity="quiz">오늘의 퀴즈</button><button data-activity="donate">공동 도시락</button><button data-activity="story">협력 이야기</button><button data-activity="work">직업 활동</button></nav><div id="compactQuiz"><span class="eyebrow">DAILY CAREER</span><h1>오늘의 직업 탐험</h1><p>하루 한 문제, 우리 마을을 연결하는 직업을 만나요.</p><button id="startCompactQuiz">퀴즈 시작</button></div></section>';
if(!campus){document.querySelector('main').prepend(activityBox);activityBox.append(document.querySelector('#growthActivities'));activityBox.onclick=e=>{const b=e.target.closest('[data-activity]');if(b){activity=b.dataset.activity;applyScreen()}};document.querySelector('#startCompactQuiz').onclick=()=>document.querySelector('#dailyQuizShortcut').click();}
const villageSections=document.createElement('nav');villageSections.className='village-sections';villageSections.setAttribute('aria-label','우리 마을 시설');villageSections.innerHTML='<button data-village-section="village">마을 지도</button><button data-village-section="market">장터</button>';if(!campus){tabs.after(villageSections);villageSections.onclick=e=>{const b=e.target.closest('[data-village-section]');if(b)navigate(b.dataset.villageSection)}}
window.villageNavigate=navigate;
function navigate(dest,replace=false){
 if(dest==='logout'){window.logoutStudent();return}
 if(dest==='teacher'){location.href='teacher.html';return}
 if(dest==='settings'||dest==='bag'){if(campus){location.href='index.html#'+dest;return}dest==='settings'?openGameSettings():openGameBag();return}
 if(dest==='travel'){passportTab='travel';dest='passport'}
 if(campus&&!['study','passport'].includes(dest)){location.href='index.html#'+dest;return}
 if(!campus&&['study','passport'].includes(dest)){location.href='campus.html#'+(passportTab==='travel'&&dest==='passport'?'travel':dest);return}
 if(!['farm','village','market','activity','study','passport'].includes(dest))dest=campus?'study':'farm';
 screen=dest;const hash='#'+dest;if(location.hash!==hash)history[replace?'replaceState':'pushState']({screen},'',hash);
 applyScreen();window.scrollTo({top:0,behavior:'instant'});
}
window.addEventListener('popstate',()=>navigate(location.hash.slice(1)||'farm',true));
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)||'farm',true));

function updateTop(){let w,day;if(!campus){w=weather();day=state.day;const wi=window.classroomActive?classroomData.room.weather:(state.day-1)%6;document.querySelector('#compactWeather').textContent=`${day}일째 · ${w.icon} ${w.name} · 게임 기온 ${[22,24,23,18,20,21][wi]}°C`;}else document.querySelector('#compactWeather').textContent=(screen==='passport'?'내 여권':'☾ 별빛도서관')+(data?.name?' · '+data.name:'');document.querySelector('#compactPrices').hidden=campus;priceBox.innerHTML=!campus?'<small>게임 속 시세 · 실제 날씨·가격이 아닙니다.</small><div>'+items.map((n,i)=>`<span>${symbols[i]} ${n} <b>${i<4?price(i):(growthBoard?.crops[i-3]?.price??'—')}</b> 코인${i>=4?' (매입가)':''}</span>`).join('')+'</div>':''}
function badgeIcon(id){return id.startsWith('streak')?'📚':id.startsWith('focus')?'◷':id.startsWith('quiz')?'💡':id.startsWith('giving')?'♡':id.startsWith('variety')?'🌿':id==='first-harvest'?'🌱':id==='kind-neighbor'?'🤝':'🧺'}
function drawBook(){document.body.dataset.passportSection=passportTab;if(screen!=='passport')return;if(campus){document.querySelector('#travelPage').hidden=passportTab!=='travel';}document.querySelector('#passportSheet').hidden=passportTab==='travel';const d=growthBoard,all=d?.badges||[],name=campus?data?.name:state.name;document.querySelector('#passportOwner').textContent=(name||'새싹 여행자')+' · 작은 일이 연결되는 시민의 기록';book.querySelectorAll('[data-passport-tab]').forEach(b=>{b.classList.toggle('selected',b.dataset.passportTab===passportTab);b.setAttribute('aria-pressed',String(b.dataset.passportTab===passportTab))});document.querySelector('#passportOriginal').hidden=passportTab!=='profile'||!campus;
const sheet=document.querySelector('#passportSheet');if(passportTab==='travel')return;if(passportTab==='profile'){sheet.innerHTML=`<h2>나의 시민 여권</h2><div class="passport-profile"><span>✦</span><div><b>${esc(name||'새싹 여행자')}</b><p>${campus?esc(data?.rooms.find(r=>r.id===data.home)?.label||'학급 입장 필요'):window.classroomActive?'학급 '+esc(classroomData.room.code)+' · '+esc(classroomData.me.accountName):'혼자 연습 중'}</p><small>획득한 도장 ${all.filter(b=>b.earned).length}개</small></div></div>${campus?'':'<button data-passport-action="settings">내 정보·설정</button><button data-passport-action="travel">여권 발급·방문 도장</button>'}`;return}
let list=passportTab==='badges'?all.filter(b=>b.earned):all;const perPage=innerWidth<740?4:6,max=Math.max(1,Math.ceil(list.length/perPage));stampPage=Math.max(0,Math.min(stampPage,max-1));sheet.innerHTML=`<h2>${passportTab==='badges'?'나의 배지':passportTab==='missions'?'다음 도장을 향한 도전':'나의 스탬프 컬렉션'}</h2><p class="passport-description">${passportTab==='stamps'?'색이 채워진 도장은 달성한 기록이에요. 회색 도장에는 다음 목표가 표시돼요.':passportTab==='badges'?'이미 획득한 도장과 배지를 모아 보아요.':'각자의 속도로 도전해요. 순위나 늦은 밤 보너스는 없어요.'}</p><div class="passport-collection">${list.slice(stampPage*perPage,(stampPage+1)*perPage).map(b=>`<article class="passport-medal ${b.earned?'earned':''}"><span class="medal-icon">${badgeIcon(b.id)}</span><b>${esc(b.title)}</b><small>${esc(b.reason)}</small><span class="medal-state">${b.earned?'✓ 획득 완료':b.value+' / '+b.target}</span>${b.earned?`<time>${new Date(b.earned).toLocaleDateString('ko-KR')}</time>`:'<span class="medal-dots">'+[1,2,3].map(n=>`<i class="${b.value/b.target>=n/3?'filled':''}"></i>`).join('')+'</span>'}</article>`).join('')||'<p>아직 획득한 배지가 없어요. 첫 수확부터 시작해 볼까요?</p>'}</div><div class="passport-pagination"><button data-stamp-page="-1" ${stampPage===0?'disabled':''}>← 이전</button><span>${stampPage+1} / ${max}</span><button data-stamp-page="1" ${stampPage+1>=max?'disabled':''}>다음 →</button></div>${!d?'<p>학급으로 입장하면 내 기록을 확인할 수 있어요.</p>':''}`}
function applyScreen(){document.body.dataset.screen=screen;document.body.dataset.activity=activity;tabs.querySelectorAll('[data-screen]').forEach(b=>{b.classList.toggle('selected',b.dataset.screen===(screen==='market'?'village':screen));b.setAttribute('aria-pressed',String(b.dataset.screen===(screen==='market'?'village':screen)))});book.hidden=screen!=='passport';villageSections.hidden=!['village','market'].includes(screen);villageSections.querySelectorAll('button').forEach(b=>b.classList.toggle('selected',b.dataset.villageSection===screen));if(campus){view=screen==='passport'&&passportTab==='travel'?'travel':'study';if(data)display(data);applyStudy()}else{if(['farm','village','market'].includes(screen)){farmView=screen==='farm';tab=screen==='market'?'market':'work'}else if(screen==='activity'){tab=activity==='story'?'season':'work';farmView=activity!=='story'}render();activityBox.querySelectorAll('[data-activity]').forEach(b=>b.classList.toggle('selected',b.dataset.activity===activity));document.querySelector('#compactQuiz').hidden=activity!=='quiz'}updateTop();drawBook();window.dispatchEvent(new Event('village-screen-change'))}
let applyStudy=()=>{};
if(campus){const studyNav=document.createElement('nav');studyNav.className='study-compact-tabs';studyNav.innerHTML='<button data-study-section="seats">자리 선택</button><button data-study-section="focus">내 집중</button><button data-study-section="history">공부 기록</button>';document.querySelector('.study-hero').after(studyNav);studyNav.onclick=e=>{const b=e.target.closest('[data-study-section]');if(b){studyTab=b.dataset.studySection;applyStudy()}};const zoneNav=document.createElement('nav');zoneNav.className='zone-tabs';zoneNav.innerHTML=[['library','도서관 1–12'],['window','창가 13–24'],['fire','서재 25–30'],['lounge','라운지']].map(([id,t])=>`<button data-zone="${id}">${t}</button>`).join('');document.querySelector('.cafe-floor').before(zoneNav);const paging=document.createElement('div');paging.className='compact-seat-paging';paging.innerHTML='<button id=previousSeatPage>← 앞 자리</button><span id=seatPageInfo></span><button id=nextSeatPage>뒤 자리 →</button>';document.querySelector('.cafe-floor').after(paging);document.querySelector('#previousSeatPage').onclick=()=>{seatPage=0;applySeatPage()};document.querySelector('#nextSeatPage').onclick=()=>{seatPage=1;applySeatPage()};function applySeatPage(){document.querySelectorAll('[data-desk]').forEach(b=>{const n=Number(b.dataset.desk),within=(n-1)%12;b.classList.toggle('compact-seat-hidden',innerWidth<740&&n<=24&&(seatPage===0?within>=6:within<6))});paging.hidden=innerWidth>=740||!['library','window'].includes(zone);document.querySelector('#previousSeatPage').disabled=seatPage===0;document.querySelector('#nextSeatPage').disabled=seatPage===1;document.querySelector('#seatPageInfo').textContent=(seatPage+1)+' / 2';}const oldSeatPlan=drawSeatPlan;drawSeatPlan=function(){oldSeatPlan();applySeatPage()};window.addEventListener('resize',applySeatPage);zoneNav.onclick=e=>{const b=e.target.closest('[data-zone]');if(b){zone=b.dataset.zone;seatPage=0;applyStudy()}};applyStudy=()=>{applySeatPage();document.body.dataset.studySection=studyTab;document.body.dataset.zone=zone;studyNav.querySelectorAll('button').forEach(b=>b.classList.toggle('selected',b.dataset.studySection===studyTab));zoneNav.querySelectorAll('button').forEach(b=>b.classList.toggle('selected',b.dataset.zone===zone))};document.querySelector('.study-interior').addEventListener('click',e=>{if(e.target.closest('[data-desk]:not(:disabled)')){studyTab='focus';applyStudy()}},true);const oldDisplay=display;display=function(d){oldDisplay(d);drawBook();updateTop()};}else{const oldRender=render;render=function(){oldRender();updateTop();drawBook()};const oldNavigate=gameNavigate;gameNavigate=function(dest){if(['farm','village','market','season','work'].includes(dest)){screen=dest==='season'||dest==='work'?'activity':dest;if(dest==='season')activity='story';if(dest==='work')activity='work';navigate(screen)}else oldNavigate(dest)}}
const oldGrowthDraw=drawGrowth;drawGrowth=function(){oldGrowthDraw();drawBook()};
const desired=location.hash.slice(1);if(['farm','village','market','activity','study','passport','travel'].includes(desired)){navigate(desired,true)}else{navigate(screen,true)}if(!campus&&['bag','settings'].includes(desired)){const wait=setInterval(()=>{if(document.querySelector('#dialog').open)return;clearInterval(wait);navigate(desired)},300)}
})();
